250	// ---------- SSH forward-port allocation ----------
251	
252	/**
253	 * `Server.sshPort` and `PortForward.publicPort` are both globally UNIQUE, so the
254	 * taken-set is read globally even though the *range* we scan is per-node.
255	 * Node-awareness therefore comes from the range: give each node a disjoint
256	 * sshPortStart/sshPortEnd window and two nodes can never collide.
257	 */
258	async function pickFreePort(tx: Tx, range: IpamRange): Promise<number> {
259	  const [servers, forwards] = await Promise.all([
260	    tx.server.findMany({
261	      where: { sshPort: { gte: range.sshPortStart, lte: range.sshPortEnd } },
262	      select: { sshPort: true },
263	    }),
264	    tx.portForward.findMany({
265	      where: { publicPort: { gte: range.sshPortStart, lte: range.sshPortEnd } },
266	      select: { publicPort: true },
267	    }),
268	  ]);
269	  const used = new Set<number>([
270	    ...servers.map((s) => s.sshPort!).filter((p) => p != null),
271	    ...forwards.map((f) => f.publicPort),
272	  ]);
273	  for (let p = range.sshPortStart; p <= range.sshPortEnd; p++) {
274	    if (used.has(p)) continue;
275	    if (isReserved(`port:${p}`)) continue;
276	    return p;
277	  }
278	  throw new Error(
279	    range.nodeId
280	      ? `SSH port pool exhausted for node ${range.nodeId} (${range.sshPortStart}-${range.sshPortEnd})`
281	      : "SSH port pool exhausted"
282	  );
283	}
