1	import type { GameFamily } from "@/lib/games";
2	
3	/**
4	 * PREVIEW-ONLY sample data for the three new game-landing DIRECTIONS
5	 * (components/marketing/gamelanding/*). Nothing here touches the live
6	 * GameLandingPage or any *-server-hosting route — it exists purely so the
7	 * preview routes render with realistic, game-specific content.
8	 *
9	 * Plans/prices are pulled from the real live pages (rust-server-hosting,
10	 * satisfactory-server-hosting, palworld) so the mock reads true.
11	 *
12	 * Social proof is split into two clearly-distinct things (2026-08-29 revision):
13	 *   - The real aggregate rating/count is <ReviewBadges/> (Google/Trustpilot/
14	 *     HostAdvice), rendered by the route page and passed in as a prop. That is
15	 *     the only place a star average or review count is ever shown.
16	 *   - `reviews` below are ILLUSTRATIVE example feedback, not real customer
17	 *     submissions — no invented personal names and no per-quote star rating
18	 *     (that would imply a specific measured score). Attribution is a generic
19	 *     `role` string (e.g. "Rust wipe admin") and every render of this data is
20	 *     required to visibly label it as illustrative/example content.
21	 */
22	
23	export type PreviewPlan = {
24	  id: string;
25	  /** Short tier label, e.g. "Wipe" / "Community". */
26	  tier: string;
27	  /** RAM headline, e.g. "6 GB". */
28	  ram: string;
29	  /** Displayed price, e.g. "$17.99". Rendered with a trailing "/mo". */
30	  price: string;
31	  /** Right-aligned spec meta, e.g. "60 slots" or "4 vCPU · 120 GB NVMe". */
32	  meta: string;
33	  /**
34	   * Advertised player-slot capacity for this plan, when it has one. Drives the
35	   * interactive pricing configurator's player-count → plan matching. Omitted for
36	   * VPS-style plans (e.g. Satisfactory) that are sized by RAM rather than slots —
37	   * those fall back to the fitted RAM curve in lib/game-player-recommend.
38	   */
39	  slots?: number;
40	  blurb: string;
41	  popular?: boolean;
42	  features: string[];
43	  /**
44	   * Regular/renewal MONTHLY price (e.g. "$17.99"), set ONLY when `price` above is
45	   * a discounted first-term intro rate. Added 2026-09-19 for the game×location
46	   * matrix (lib/marketing/gameLocationLandings.ts's adapter), which prices plans
47	   * from live `GamePlan.priceCents`/`introPriceCents` and must disclose the
48	   * renewal the same way PricingGrid.tsx already does — optional so every
49	   * existing PREVIEW_GAMES entry below (flat `price`, no intro/renewal split)
50	   * renders exactly as before.
51	   */
52	  renewalPrice?: string;
53	};
54	
55	/** Icon keys resolved to real <Icon*> components inside the client kit. */
56	export type IconKey =
57	  | "bolt"
58	  | "apps"
59	  | "terminal"
60	  | "shield"
61	  | "gauge"
62	  | "users"
63	  | "backup"
64	  | "globe"
65	  | "scale";
66	
67	export type PreviewReason = {
68	  n: string;
69	  title: string;
70	  body: string;
71	  icon: IconKey;
72	};
73	
74	/**
75	 * ILLUSTRATIVE example feedback — NOT a real customer submission. No invented
76	 * personal name and no per-quote star rating (the real aggregate score lives
77	 * in <ReviewBadges/> only). `role` is a generic descriptor, e.g. "Rust wipe
78	 * admin", never a fabricated name.
79	 */
80	export type PreviewReview = {
81	  id: string;
82	  quote: string;
83	  role: string;
84	};
85	
86	export type PreviewGame = {
87	  family: GameFamily;
88	  /** public/games/art/<artSlug>_hero.jpg + _poster.jpg */
89	  artSlug: string;
90	  name: string;
91	  /** Small uppercase category line. */
92	  kicker: string;
93	  /** Hero headline (plain) + gradient highlight fragment. */
94	  headline: string;
95	  highlight: string;
96	  /** One-line deck under the headline. */
97	  deck: string;
98	  fromPrice: string;
99	  /** Art-derived, on-brand accent (violet / cyan family). */
100	  accent: string;
101	  /** Second art-derived hue, ambient glows only. */
102	  glow: string;
103	  /** Live-panel identity. */
104	  worldName: string;
105	  region: string;
106	  /** Terminal boot lines for the console direction. */
107	  boot: string[];
108	  plans: PreviewPlan[];
109	  reasons: PreviewReason[];
110	  reviews: PreviewReview[];
111	  /**
112	   * Overrides the hero trust-strip's "Singapore · low latency" chip. Added
113	   * 2026-09-19 for the game×location matrix — when a page is built for a
114	   * specific location (via lib/marketing/gameLocationLandings.ts's adapter),
115	   * this carries that location's own honest latency framing instead. Absent on
116	   * every existing PREVIEW_GAMES entry, so the 40 live per-game pages keep
117	   * showing the original Singapore-default chip unchanged.
118	   */
119	  trustLatencyLabel?: string;
120	  /**
121	   * A distinctly-labeled honesty note rendered in the hero, directly under the
122	   * headline — added 2026-09-19 for the game×location matrix. `text` is reused
123	   * VERBATIM from that location's `GameLocationDef.hub` sentence in
124	   * gameLocationLandings.ts (never rewritten/templated here), and `flagCode` is
125	   * rendered through the real-image <CountryFlag/>, never emoji. Absent (and
126	   * therefore not rendered) on every existing PREVIEW_GAMES entry.
127	   */
128	  locationNote?: { flagCode: string; text: string };
129	  /**
130	   * Honest nearest-real-region hint (e.g. "sgp1"/"fsn1") passed through to
131	   * every Deploy link's `deployHref({ region })` on a game×location combo
132	   * page, pre-selecting the wizard's region picker without ever implying a
133	   * region that isn't genuinely closer (undefined for the "market" locations
134	   * — the wizard just falls back to its own default). Absent on every
135	   * existing PREVIEW_GAMES entry (deploy links omit `region`, unchanged).

