import { Section, SectionTitle } from "@/components/marketing/primitives";
import { FaqJsonLd, ProductOffersJsonLd, APP_URL } from "@/components/marketing/StructuredData";

/**
 * LIVE — flagship "Combined" game-landing design, Wave 11 (2026-09-24).
 *
 * PREVIEW_GAMES.ets2 was authored directly from the real seeded GamePlan rows
 * (prisma/seed-wave11-games.ts — 1GB/8-player $2.99, 2GB/8-player $4.99
 * popular, 4GB/8-player $7.99), so no price override is needed here.
 *
 * IMPORTANT, honestly stated in the FAQ below: this is SCS Software's
 * "Convoy" dedicated server, not a full multiplayer mod like TruckersMP — max
 * 8 players is SCS's own real, officially-supported ceiling (see
 * lib/game-config.ts's ETS2 schema for the citation). The server boots on the
 * base map with no DLC/mods the moment it's provisioned; a customer who owns
 * paid DLC maps or wants mods active uploads their own server_packages.sii/
 * .dat (exported from their own game client) over SFTP — see
 * lib/game-mods.ts's `ets2` entry for the exact steps, surfaced here in the
 * FAQ too since there is no in-app upload flow (nor does one need to exist —
 * full SFTP/file-manager access already covers it, see lib/game-config.ts's
 * Wave 11 header for the full research on why).
 */

export const metadata: Metadata = {
  title: "Euro Truck Simulator 2 Server Hosting — Instant Setup",
  description:
    "Managed Euro Truck Simulator 2 Convoy dedicated server hosting from $2.99/mo. Bring your own owned DLC maps and mods over SFTP, full admin control, instant setup on a low-latency Singapore network.",
  alternates: { canonical: "/euro-truck-simulator-2-server-hosting" },
  openGraph: {
    type: "article",
    title: "Euro Truck Simulator 2 Server Hosting — Instant Setup",
    description:
      "Managed ETS2 Convoy hosting: bring your own owned DLC maps and mods over SFTP, full admin control, instant setup on a low-latency Singapore network. From $2.99/mo.",
    url: `${APP_URL}/euro-truck-simulator-2-server-hosting`,
  },
};

const GAME = PREVIEW_GAMES.ets2;

const FAQ = [
  {
    q: "What is the ETS2 Convoy dedicated server?",
    a: "It's SCS Software's own official multiplayer tool for Euro Truck Simulator 2 — up to 8 players haul together on one persistent server, separate from third-party mods like TruckersMP.",
  },
  {
    q: "Why only 8 players?",
    a: "That's SCS's own real, officially-supported ceiling for a Convoy server. A higher count needs an unsupported client-side console hack every single player would have to apply individually — not something we sell as a paid upsell.",
  },
  {
    q: "Do I need to upload anything to get started?",
    a: "No — your server boots and hosts a working base-map convoy the moment it's provisioned, with zero setup. Uploading your own game files is only needed if you want your owned DLC maps or mods active.",
  },
  {
    q: "How do I add my owned DLC maps or mods?",
    a: "In ETS2 itself (not the server): turn on the console (config.cfg: uset g_console \"1\"), load any save, press ~, and run export_server_packages. That writes server_packages.sii and server_packages.dat to your game's save folder — upload both over SFTP/File Manager to your server, overwriting the two files already there, then restart. These files mirror your own game's exact DLC and mod setup; there's no way for us (or anyone) to generate a valid one on your behalf.",
  },
  {
    q: "Which plan do I need?",
    a: "The 1 GB Solo Convoy plan at $2.99 suits a small regular crew on the base map. The 2 GB Standard Convoy plan at $4.99 is our popular pick, with headroom for a DLC map or two. Choose the 4 GB Modded Convoy plan at $7.99 for ProMods or a heavier mod list.",
  },
  {
    q: "How quickly is my server ready?",
    a: "Setup is instant — your ETS2 server is provisioned and online within minutes of ordering.",
  },
];

const RELATED = [
  { label: "All game servers", href: "/game-servers" },
  { label: "American Truck Simulator hosting", href: "/american-truck-simulator-server-hosting" },
  { label: "Pricing", href: "/pricing" },
];

export default function Ets2ServerHostingPage() {
  return (
    <>
      <FaqJsonLd items={FAQ} />
      <ProductOffersJsonLd
        name="Nxeon Euro Truck Simulator 2 Server Hosting"
        description={GAME.deck}
        url={`${APP_URL}/game-servers`}
        offers={GAME.plans.map((p) => ({
          name: `${GAME.name} ${p.tier} (${p.ram})`,
          price: parseFloat(p.price.replace(/[^0-9.]/g, "")),
        }))}
      />

      <GameLandingCombined game={GAME} reviewBadges={<ReviewBadges />} />

      {/* FAQ */}
      <Section tone="base" size="md">
        <SectionTitle eyebrow="FAQ" title="Questions, answered" />
        <div className="mx-auto mt-10 max-w-3xl space-y-3">
          {FAQ.map((f) => (
            <details key={f.q} className="card group">
              <summary className="cursor-pointer list-none font-medium text-white marker:content-none">
                <span className="flex items-center justify-between gap-4">
                  {f.q}
                  <span className="text-slate-500 transition-transform group-open:rotate-45">+</span>
                </span>
              </summary>
              <p className="mt-3 text-sm leading-relaxed text-slate-400">{f.a}</p>
            </details>
          ))}
        </div>
      </Section>

      {/* Related */}
      <Section tone="base" size="sm">
        <div className="mx-auto flex max-w-3xl flex-wrap items-center justify-center gap-2">
          <span className="text-xs font-semibold uppercase tracking-wider text-slate-500">Related</span>
          {RELATED.map((r) => (
            <Link
              key={r.href}
              href={r.href}
              className="rounded-full border border-white/10 bg-white/[0.03] px-3 py-1 text-sm text-slate-300 transition-colors hover:border-white/20 hover:text-white"
            >
              {r.label}
            </Link>
          ))}
        </div>
      </Section>
    </>
  );
}

